import yaml,re
src=open('claude-dev-log-diary/day-021.md').read()
# normalize: collapse whitespace/newlines
norm=re.sub(r'\s+',' ',src)
d=yaml.safe_load(open('.coordination/mining/pairing/day-021.yaml'))
def chk(q,label):
    if not q: return
    for part in q.split(' ... '):
        p=re.sub(r'\s+',' ',part).strip()
        if p and p not in norm:
            print('MISS',label,'::',p[:90])
for r in d['pairing_rules']: chk(r.get('quote',''),r['rule_id'])
for a in d['anti_patterns']: chk(a.get('quote',''),a['name'])
for p in d['philosophy']: chk(p.get('quote',''),p['loc'])
for e in d['council_episodes']:
    for f in e['fidelity']:
        for m in re.findall(r"'([^']{25,})'", f['evidence']):
            pm=re.sub(r'\s+',' ',m).strip()
            if pm not in norm: print('MISS-FID',e['loc'],'::',pm[:90])
print('done')
EOF
